1	// Replay runner (DESIGN.md §"Replay at the parent commit", §"Grade"): for each (task, setup), a sandbox at the
2	// task's parent commit, the setup's rules, the harness, a grade in a separate copy, failure codes, one Replay row.
3	//
4	//   const replays = await runReplays({ repo, tasks, setups, workRoot, maxCostUsd: 5 });
5	//
6	// Never throws for one run going wrong: a harness error is a Replay with verdict agent_error. Runs that are not
7	// started (unavailable candidate, budget reached, unsupported harness) are reported through `onSkip`.
8	
9	import { chmodSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
10	import { homedir, tmpdir } from "node:os";
11	import { join, posix, resolve, sep } from "node:path";
12	import { runClaude } from "../harness/claude.ts";
13	import type { HarnessResult } from "../harness/types.ts";
14	import { grade, isTestFile, type GradeResult } from "../grade/index.ts";
15	import { classify, parseTranscript, type Transcript } from "../grade/taxonomy.ts";
16	import { createSandbox, destroySandbox, proveIsolation, runGit, type IsolationProof } from "../sandbox/index.ts";
17	import { identify } from "../identity/index.ts";
18	import { fetchCheckpoints } from "../ingest/fetch.ts";
19	import { parseCheckpoints } from "../ingest/parse.ts";
20	import { loadSetups, type RunnableSetup } from "../setups/registry.ts";
21	import { FailureCode, type Replay, type ReplayVerdict } from "../types.ts";
22	import type { ReplayBatch, ToolBackend } from "../agent/tools.ts";
23	import { planReplayTasks, type ReplayTask } from "./tasks.ts";
24	
25	export interface SkippedRun {
26	  task: string;
27	  setup: string;
28	  reason: string;
29	}
30	
31	export interface RunReplaysOptions {
32	  /** Local path of the repo the tasks come from. */
33	  repo: string;
34	  tasks: ReplayTask[];
35	  setups: RunnableSetup[];
36	  /** Sandboxes go here. Must not be under $HOME. */
37	  workRoot: string;
38	  /** Concurrent runs. Default 3. */
39	  parallel?: number;
40	  /** No new run starts once the summed cost of finished runs reaches this. */
41	  maxCostUsd: number;
42	  harness?: typeof runClaude;
43	  planId?: string;
44	  attempt?: number;
45	  /** Spend cap per harness run, also bounded by what is left of maxCostUsd. Default 2. */
46	  perRunUsd?: number;
47	  /** Explicit turn cap for every run; wins over the per-task cap from `turnCap`. */
48	  maxTurns?: number;
49	  timeoutMs?: number;
50	  /** Test command for grading; default: detected from the sandbox. */
51	  testCmd?: string;
52	  /** The real `claude` binary the setting-sources shim execs. Default "claude" on the child's PATH. */
53	  claudeBin?: string;
54	  keepSandboxes?: boolean;
55	  onSkip?: (s: SkippedRun) => void;
56	}
57	
58	const DEFAULT_PARALLEL = 3;
59	const DEFAULT_PER_RUN_USD = 2;
60	const MIN_TURN_CAP = 60;
61	const UNKNOWN_TURN_CAP = 80;
62	const DEFAULT_TIMEOUT_MS = 20 * 60_000;
63	export const LOCAL_RULES_NAME = "CLAUDE.local.md";
64	export const SETTING_SOURCES = "project,local";
65	
66	/** Turn cap for a task: twice the original session's turns (at least 60), or 80 when that is unknown. */
67	export function turnCap(task: Pick<ReplayTask, "originalTurns">, explicit?: number): number {
68	  if (explicit !== undefined) return explicit;
69	  return task.originalTurns === null ? UNKNOWN_TURN_CAP : Math.max(MIN_TURN_CAP, Math.ceil(2 * task.originalTurns));
70	}
71	
72	/** Default work root: the OS temp dir, never $HOME. */
73	export function defaultWorkRoot(): string {
74	  return join(tmpdir(), "roster-replays");
75	}
76	
77	function underHome(path: string): boolean {
78	  const home = resolve(homedir());
79	  const p = resolve(path);
80	  return p === home || p.startsWith(home + sep);
81	}
82	
83	/**
84	 * The harness pins `--setting-sources project`; replays also load CLAUDE.local.md, which needs `local`.
85	 * This shim rewrites that one value and execs the real binary.
86	 */
87	export function writeSettingSourcesShim(dir: string, target = "claude"): string {
88	  mkdirSync(dir, { recursive: true });
89	  const path = join(dir, "claude-setting-sources");
90	  const q = (s: string) => `'${s.replace(/'/g, `'\\''`)}'`;
91	  writeFileSync(
92	    path,
93	    `#!/bin/bash
94	# Written by src/replay/run.ts: --setting-sources project -> ${SETTING_SOURCES}
95	args=(); prev=""
96	for a in "$@"; do
97	  if [ "$prev" = "--setting-sources" ] && [ "$a" = "project" ]; then a=${q(SETTING_SOURCES)}; fi
98	  args+=("$a"); prev="$a"
99	done
100	exec ${q(target)} "\${args[@]}"
101	`,
102	  );
103	  chmodSync(path, 0o755);
104	  return path;
105	}
106	
107	/** Why a setup cannot run, or null when it can. */
108	function unavailable(setup: RunnableSetup): string | null {
109	  if (setup.candidate && Object.keys(setup.env).length === 0) return "unavailable";
110	  if (setup.harness !== "claude-code") return `unsupported harness ${setup.harness}`;
111	  return null;
112	}
113	
114	/** Directories the original change touched, for the scope guard. */
115	function touchedDirs(repo: string, task: ReplayTask): string[] | undefined {
116	  try {
117	    const files = runGit(repo, ["diff", "--name-only", task.parentSha, task.originalSha]).split("\n").filter(Boolean);
118	    return [...new Set(files.map((f) => posix.dirname(f)))];
119	  } catch {
120	    return undefined;
121	  }
122	}
123	
124	/**
125	 * The harness writes `--output-format json` (one result object), not stream-json. Both parse here; a result-only
126	 * transcript has no tool calls, so it carries no evidence for F2.
127	 */
128	function loadTranscript(path: string | null): { t: Transcript; hasCalls: boolean } {
129	  let text = "";
130	  try {
131	    if (path && existsSync(path)) text = readFileSync(path, "utf8");
132	  } catch {}
133	  let t = parseTranscript(text);
134	  if (t.turns === 0 && t.result === null && text.trim()) {
135	    try {
136	      const j = JSON.parse(text);
137	      t = parseTranscript((Array.isArray(j) ? j : [j]).map((e) => JSON.stringify(e)).join("\n"));
138	    } catch {}
139	  }
140	  return { t, hasCalls: t.turns > 0 };
141	}
142	
143	function verdictOf(g: GradeResult, hasHidden: boolean): ReplayVerdict {
144	  if (hasHidden && !g.hiddenPass) return "hidden_tests_failed";
145	  if (!g.suitePass) return "suite_failed";
146	  if (!g.scopeOk) return "guardrail_flagged";
147	  return "pass";
148	}
149	
150	const ERROR_CODE: Partial<Record<string, FailureCode>> = {
151	  timeout: FailureCode.F5,
152	  max_turns: FailureCode.F5,
153	  budget: FailureCode.F5,
154	  spawn_failed: FailureCode.F6,
155	  setup_failed: FailureCode.F6,
156	};
157	
158	/** One (task, setup) run. Never throws. */
159	async function runOne(
160	  o: RunReplaysOptions & { harness: typeof runClaude; bin: string },
161	  task: ReplayTask,
162	  setup: RunnableSetup,
163	  budgetUsd: number,
164	): Promise<Replay> {
165	  const attempt = o.attempt ?? 1;
166	  const planId = o.planId ?? "adhoc";
167	  const row: Replay = {
168	    id: `${planId}:${task.id}:${setup.id}:${attempt}`,
169	    plan_id: planId,
170	    task_session_id: task.id,
171	    setup_id: setup.id,
172	    attempt,
173	    isolation_proof: "",
174	    turns: null,
175	    duration_ms: null,
176	    cost_usd: null,
177	    hidden_pass: null,
178	    suite_pass: null,
179	    scope_ok: null,
180	    judge_equiv: null,
181	    failure_codes: [],
182	    verdict: "agent_error",
183	    transcript_ref: null,
184	    trace_url: null,
185	    error: null,
186	    turn_cap: turnCap(task, o.maxTurns),
187	  };
188	  const fail = (code: FailureCode, why: string): Replay => {
189	    row.failure_codes = [code];
190	    row.error = why;
191	    if (!row.isolation_proof) row.isolation_proof = JSON.stringify({ ok: false, checks: [], error: why });
192	    return row;
193	  };
194	
195	  let sandboxPath: string | null = null;
196	  try {
197	    const sb = await createSandbox(o.repo, task.parentSha, { root: o.workRoot });
198	    sandboxPath = sb.path;
199	    const proof: IsolationProof = await proveIsolation(sb.path, o.repo, task.parentSha);
200	    row.isolation_proof = JSON.stringify(proof);
201	    if (!proof.ok) return fail(FailureCode.F6, "isolation proof failed");
202	
203	    // Rules in, committed as `setup:` so neither the agent's diff nor the grade sees them.
204	    writeFileSync(join(sb.path, "CLAUDE.md"), readFileSync(setup.rulesPath, "utf8"));
205	    const ruleFiles = ["CLAUDE.md"];
206	    if (setup.extraRulesPath) {
207	      writeFileSync(join(sb.path, LOCAL_RULES_NAME), readFileSync(setup.extraRulesPath, "utf8"));
208	      ruleFiles.push(LOCAL_RULES_NAME);
209	    }
210	    runGit(sb.path, ["add", "-f", "--", ...ruleFiles]);
211	    // --allow-empty: the repo's own CLAUDE.md may already equal the setup's rules (replaying this repo's own tasks).
212	    runGit(sb.path, [
213	      "-c",
214	      "commit.gpgsign=false",
215	      "commit",
216	      "-q",
217	      "--allow-empty",
218	      "-m",
219	      `setup: ${ruleFiles.join(" + ")} for ${setup.id}`,
220	    ]);
221	    const rulesSha = runGit(sb.path, ["rev-parse", "HEAD"]);
222	
223	    let res: HarnessResult | null = null;
224	    let harnessError: string | null = null;
225	    try {
226	      res = await o.harness({
227	        sandboxPath: sb.path,
228	        prompt: task.prompt,
229	        model: setup.model,
230	        rulesFile: setup.rulesPath,
231	        maxTurns: row.turn_cap!,
232	        timeoutMs: o.timeoutMs ?? DEFAULT_TIMEOUT_MS,
233	        budgetUsd,
234	        env: setup.env,
235	        bin: o.bin,
236	      });
237	    } catch (e) {
238	      harnessError = e instanceof Error ? e.message : String(e);
239	    }
240	    if (!res) return fail(FailureCode.F6, `harness threw: ${harnessError}`);
241	
242	    row.turns = res.turns;
243	    row.duration_ms = res.durationMs;
244	    row.cost_usd = res.costUsd;
245	    row.transcript_ref = res.transcriptPath;
246	    const { t, hasCalls } = loadTranscript(res.transcriptPath);
247	
248	    if (res.isError) {
249	      row.error = res.errorKind ?? "agent_error";
250	      const codes = new Set(classify({ verdict: "agent_error" }, null, t).map((c) => c.code));
251	      const forced = res.errorKind ? ERROR_CODE[res.errorKind] : undefined;
252	      if (forced === FailureCode.F6) codes.clear();
253	      if (forced) codes.add(forced);
254	      if (!hasCalls) codes.delete(FailureCode.F2);
255	      // A result-only transcript of an errored run is not a kill: drop the "no result event" F5 unless forced.
256	      if (t.result === null && forced !== FailureCode.F5 && !hasCalls) codes.delete(FailureCode.F5);
257	      row.failure_codes = Object.values(FailureCode).filter((c) => codes.has(c));
258	      return row;
259	    }
260	
261	    // The agent's base is the setup commit (the harness's own when it made one).
262	    const base = res.setupSha ?? rulesSha;
263	    runGit(sb.path, ["add", "-A"]);
264	    const changed = runGit(sb.path, ["diff", "--cached", "--name-only", base]).split("\n").filter(Boolean);
265	    let g: GradeResult | null = null;
266	    if (changed.length === 0) row.verdict = "no_changes";
267	    else {
268	      const preexistingTests = runGit(sb.path, ["ls-tree", "-r", "--name-only", base]).split("\n").filter(isTestFile);
269	      g = await grade({
270	        sandbox: { path: sb.path, baseSha: base },
271	        hidden: task.hiddenTests,
272	        testCmd: o.testCmd,
273	        preexistingTests,
274	        touchedDirs: touchedDirs(o.repo, task),
275	      });
276	      const hasHidden = task.hiddenTests.length > 0;
277	      row.hidden_pass = hasHidden ? g.hiddenPass : null;
278	      row.suite_pass = g.suitePass;
279	      row.scope_ok = g.scopeOk;
280	      row.verdict = verdictOf(g, hasHidden);
281	    }
282	    // The run finished without error, so a missing result event is not a kill.
283	    const result = t.result ?? { subtype: "success", isError: false, numTurns: res.turns, terminalReason: res.stopReason };
284	    const codes = classify({ verdict: row.verdict }, g, { ...t, result }).map((c) => c.code);
285	    row.failure_codes = hasCalls ? codes : codes.filter((c) => c !== FailureCode.F2);
286	    return row;
287	  } catch (e) {
288	    // Sandbox, rules or grading broke: the environment, not the agent.
289	    row.verdict = "agent_error";
290	    row.hidden_pass = row.suite_pass = row.scope_ok = null;
291	    return fail(FailureCode.F6, e instanceof Error ? e.message : String(e));
292	  } finally {
293	    if (sandboxPath && !o.keepSandboxes) await destroySandbox(sandboxPath);
294	  }
295	}
296	
297	export interface ReplayRunnerDeps {
298	  /** The repo under review (git URL or local path), as given to `roster run`. */
299	  repo?: string;
300	  cacheDir: string;
301	  /** Where setups/ lives. Default: the working directory. */
302	  setupsRoot?: string;
303	  env?: Record<string, string | undefined>;
304	  workRoot?: string;
305	  parallel?: number;
306	  harness?: typeof runClaude;
307	  testCmd?: string;
308	}
309	
310	/** The coordinator's `runReplays` dependency: resolves task and setup ids, then runs them. */
311	export function replayRunner(deps: ReplayRunnerDeps): ToolBackend["runReplays"] {
312	  return async ({ plan_id, tasks: taskIds, setups: setupIds, max_cost_usd }) => {
313	    if (!deps.repo) throw new Error("no repo configured for replays");
314	    const f = await fetchCheckpoints(deps.repo, { cacheDir: deps.cacheDir });
315	    if (f.backend === "none") throw new Error("no Entire checkpoints found in this repo");
316	    const sessions = parseCheckpoints(f.repoPath, f.backend === "refs" ? "git-refs" : "branch").map((s) => ({
317	      ...s,
318	      setup_id: identify(s, f.repoPath).setupId,
319	    }));
320	    const planned = new Map(planReplayTasks(f.repoPath, sessions, []).tasks.map((t) => [t.id, t]));
321	    const missingTasks = taskIds.filter((t) => !planned.has(t));
322	    if (missingTasks.length) throw new Error(`no replayable task for session(s) ${missingTasks.join(", ")}`);
323	    const known = new Map(loadSetups(deps.setupsRoot ?? process.cwd(), deps.env ?? process.env).map((s) => [s.id, s]));
324	    const missingSetups = setupIds.filter((s) => !known.has(s));
325	    if (missingSetups.length) throw new Error(`unknown setup(s) ${missingSetups.join(", ")}`);
326	
327	    const skipped: SkippedRun[] = [];
328	    const replays = await runReplays({
329	      repo: f.repoPath,
330	      tasks: taskIds.map((t) => planned.get(t)!),
331	      setups: setupIds.map((s) => known.get(s)!),
332	      workRoot: deps.workRoot ?? defaultWorkRoot(),
333	      parallel: deps.parallel,
334	      maxCostUsd: max_cost_usd,
335	      harness: deps.harness,
336	      testCmd: deps.testCmd,
337	      planId: plan_id,
338	      onSkip: (s) => skipped.push(s),
339	    });
340	    const cost_usd = replays.reduce((s, r) => s + (r.cost_usd ?? 0), 0);
341	    return { replays, cost_usd, skipped } as ReplayBatch;
342	  };
343	}
344	
345	export async function runReplays(opts: RunReplaysOptions): Promise<Replay[]> {
346	  const workRoot = resolve(opts.workRoot);
347	  if (underHome(workRoot)) throw new Error(`workRoot ${workRoot} is under $HOME; replays must run outside it`);
348	  mkdirSync(workRoot, { recursive: true });
349	  const bin = writeSettingSourcesShim(join(workRoot, "bin"), opts.claudeBin);
350	  const o = { ...opts, workRoot, harness: opts.harness ?? runClaude, bin };
351	  const skip = (task: string, setup: string, reason: string) => opts.onSkip?.({ task, setup, reason });
352	
353	  const queue: Array<{ task: ReplayTask; setup: RunnableSetup; order: number }> = [];
354	  for (const task of opts.tasks) {
355	    for (const setup of opts.setups) {
356	      const why = unavailable(setup);
357	      if (why) skip(task.id, setup.id, why);
358	      else queue.push({ task, setup, order: queue.length });
359	    }
360	  }
361	
362	  const out: Array<{ order: number; replay: Replay }> = [];
363	  let spent = 0;
364	  let next = 0;
365	  const worker = async () => {
366	    while (next < queue.length) {
367	      const job = queue[next++]!;
368	      const left = opts.maxCostUsd - spent;
369	      if (left <= 0) {
370	        skip(job.task.id, job.setup.id, `budget: spent $${spent.toFixed(4)} of $${opts.maxCostUsd}`);
371	        continue;
372	      }
373	      const replay = await runOne(o, job.task, job.setup, Math.min(opts.perRunUsd ?? DEFAULT_PER_RUN_USD, left));
374	      spent += replay.cost_usd ?? 0;
375	      out.push({ order: job.order, replay });
376	    }
377	  };
378	  const n = Math.max(1, Math.floor(opts.parallel ?? DEFAULT_PARALLEL));
379	  await Promise.all(Array.from({ length: Math.min(n, queue.length) }, worker));
380	  return out.sort((a, b) => a.order - b.order).map((x) => x.replay);
381	}
